@qml.qnode(dev, diff_method="parameter-shift")
def circuit(theta):
    qml.RY(theta[0], wires=0)
    qml.CNOT(wires=[0, 1])
    qml.RZ(theta[1], wires=1)
    return qml.expval(qml.PauliZ(0))

