  use q = Qubit();        // allocate
  // guaranteed |0⟩ on allocation
  H(q);
  CNOT(q, q2);
  let r = M(q);          // measure
  Reset(q);              // reset before release
  // q automatically released at end of scope

ADJOINT AND CONTROLLED GENERATION:
